public int myAtoi(String s) {
    if (s == null || s.isEmpty()) return 0;

    int i = 0, n = s.length();

    // 1. 跳过前导空格
    while (i < n && s.charAt(i) == ' ') i++;
    if (i == n) return 0;

    // 2. 处理符号
    int sign = 1;
    if (s.charAt(i) == '+') {
        i++;
    } else if (s.charAt(i) == '-') {
        sign = -1;
        i++;
    }

    // 3. 逐字符累加，每步溢出预判
    int result = 0;
    while (i < n) {
        char c = s.charAt(i);
        if (c < '0' || c > '9') break;

        int digit = c - '0';
        // 关键：累加前预判，避免回绕
        if (result > (Integer.MAX_VALUE - digit) / 10) {
            return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
        }
        result = result * 10 + digit;
        i++;
    }

    return sign * result;
}
